import (
  "fmt"
  "sync"
  "my/module/cbgo"
)

func main() {
  inputs := []string{"hello","world"}
  var wg sync.WaitGroup
  wg.Add(2)
  for _, s := range inputs {
    go func(str string){
      defer wg.Done()
      b, _ := cbgo.EncodeBlob(str)
      fmt.Printf("%s -> %d bytes\n", str, len(b))
    }(s)
  }
  wg.Wait()
}
